def cards(limit=6):
 return '<div class="service-grid">'+''.join(f'<a class="service-card" href="service-{slug}.html"><span class="card-top"><span class="icon-box">{icon(ic)}</span><span class="number">0{i+1}</span></span><h3>{name}</h3><p>{desc}</p><span class="text-link">Explore service {icon("arrow")}</span></a>' for i,(slug,name,tag,desc,ic,items,prep) in enumerate(services[:limit]))+'</div>'
def heading(eyebrow,title,text='',light=False):return f'<div class="section-heading {"light" if light else ""}"><span class="eyebrow">{eyebrow}</span><h2>{title}</h2><p>{text}</p></div>'
def hero(eyebrow,title,text,image='port'):
 return f'<section class="page-hero"><div class="container page-hero-grid"><div><div class="breadcrumb"><a href="index.html">Home</a><span>/</span>{eyebrow}</div><span class="eyebrow">JKM GLOBAL TRADERS</span><h1>{title}</h1><p>{text}</p></div><img src="assets/images/{image}.jpg" alt="{dict(port="Container port and international shipping",warehouse="Organised warehouse and cargo operations",meeting="People working together on a business project",products="Product selection and purchasing")[image]}" fetchpriority="high"></div></section>'
