def page(filename,title,description,body):
 header='<div class="topbar"><div class="container"><span>Connecting Markets. Delivering Value.</span><a href="tel:+255766109131">+255 766 109 131</a><a href="tel:+255699830601">+255 699 830 601</a></div></div><header class="header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="JKM Global Traders home"><img src="assets/images/jkm-monogram.jpg" alt="" width="92" height="64"><span>JKM<span>GLOBAL TRADERS</span></span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="main-nav"><span></span><span></span><span></span></button><nav id="main-nav" aria-label="Main navigation">'+''.join(f'<a href="{url}" {"aria-current=\"page\"" if filename==url else ""}>{label}</a>' for url,label in nav)+f'<a class="nav-cta" href="contact.html" {"aria-current=\"page\"" if filename=="contact.html" else ""}>Get a quote ↗</a></nav></div></header>'
