page('how-it-works.html','How it works','Follow the JKM process from sourcing brief to quotation, purchasing and delivery coordination.',hero('Our process','A clear process.<br>From start to finish.','Know what happens next, what we need from you and where your approval is required.')+'<section class="section container"><div class="timeline">'+''.join(f'<article><span class="step-number">0{i+1}</span><div><span class="eyebrow">{out}</span><h2>{t}</h2><p>{d}</p></div></article>' for i,(t,d,out) in enumerate(process))+'</div></section><section class="section soft"><div class="container">'+heading('COMMON QUESTIONS','Before you get started.')+'<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in [('Can I send a photo instead of a product name?','Yes. Include clear photos, any model numbers, approximate quantities and your destination so we can understand your request.'),('Are shipping and customs charges included?','Only where explicitly included in your quotation. We clarify which charges are included, estimated or payable separately.'),('How long does a sourcing request take?','It depends on the product, supplier response, specifications and destination. We discuss the expected next steps after reviewing your brief.'),('Can you work with a supplier I have already found?','Yes. Tell us whether you need document checks, inspection coordination, purchasing support or logistics coordination.')])+'</div></div></section>'+cta())
