page('portal.html','Staff portal','Secure access for authorised JKM staff to manage website enquiries.','<section class="section container portal"><div id="portal-login" class="login-card">'+heading('JKM WORKSPACE','Welcome back.','Sign in with your authorised staff account to view website requests.')+'<form id="login-form"><label>Email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="button" type="submit">Sign in '+icon('arrow')+'</button><p id="login-status" class="form-status" role="status"></p></form><p class="small">Access is restricted to accounts provisioned by JKM.</p></div><div id="portal-dashboard" hidden><div class="dashboard-top"><div><span class="eyebrow">JKM WORKSPACE</span><h1>Website requests</h1></div><button id="logout" class="button secondary">Sign out</button></div><div class="dashboard-filters"><label>Filter by status<select id="status-filter"><option value="all">All requests</option><option>new</option><option>reviewing</option><option>quoted</option><option>closed</option></select></label><button id="refresh" class="button secondary">Refresh</button></div><p id="dashboard-status" role="status"></p><div id="requests-list"></div></div></section><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.49.8/dist/umd/supabase.min.js" defer></script><script src="assets/js/portal.js" defer></script>')
page('privacy.html','Privacy policy','How JKM handles details you submit through our website.',hero('Privacy','Your information.<br>Handled with care.','This notice explains how information submitted through this website is used.')+'<section class="section container legal"><h2>Information you provide</h2><p>Our enquiry form collects your name, contact details, company where provided, sourcing requirements and any reference files you choose to upload. Do not submit passwords, payment-card information or identity documents through this form.</p><h2>Why we use it</h2><p>We use your information to review your request, contact you, prepare proposals and coordinate agreed services. Relevant details may be shared with suppliers or logistics partners when needed for the work you request.</p><h2>Storage and access</h2><p>Submitted requests are stored in our Supabase-backed system with access restricted to authorised staff. Files are kept in private storage. Staff should retain information only for the enquiry, service and applicable record-keeping needs.</p><h2>Your choices</h2><p>Contact us on +255 699 830 601 to request access, correction or deletion of your enquiry information. We may need to verify your identity. Some records may need to be retained for contractual or legal reasons.</p><h2>External services</h2><p>WhatsApp and any social platforms you visit operate under their own privacy policies. Where enabled, Cloudflare Turnstile helps protect our form against automated submissions. This website does not use advertising or analytics cookies by default.</p><h2>Contact</h2><p>For questions about this notice, contact JKM using the phone numbers or WhatsApp link on our contact page.</p></section>')
page('terms.html','Terms of use','Website terms and the basis of JKM enquiries and proposals.',hero('Terms of use','Clear terms.<br>From the beginning.','Please read these points before sending a request or using information on our website.')+'<section class="section container legal"><h2>Website information</h2><p>Service descriptions explain the type of support we can assess and coordinate. They are not a binding offer, product availability statement or delivery guarantee.</p><h2>Requests and quotations</h2><p>Submitting a form does not create an order. Prices, service fees, payment terms, inspection scope, shipping responsibilities and timelines must be confirmed in the order-specific quotation or agreement.</p><h2>Partner services</h2><p>Some activities, including freight, inspection, warehousing and customs clearance, may be provided by third parties. The quotation should identify the agreed responsibilities and any exclusions.</p><h2>Customer requirements</h2><p>Provide accurate specifications, quantities, contact details and destination information. Product approvals and any compliance requirements must be discussed before purchasing.</p><h2>Estimates and advice</h2><p>Indicative costs and timing can change before confirmation. Trade consulting is general commercial support; specialist legal, tax or regulatory advice should be obtained from appropriately qualified advisers.</p><h2>Questions</h2><p>Ask our team to clarify any terms before accepting a quotation or making a payment.</p></section>')
print('Generated',len(list(ROOT.glob('*.html'))),'independent HTML pages')
# The deployable bundle includes public files only; SQL, docs and tools stay outside it.
import shutil
DIST=ROOT/'dist'
if DIST.exists():shutil.rmtree(DIST)
DIST.mkdir()
for file in ROOT.glob('*.html'):shutil.copy2(file,DIST/file.name)
shutil.copytree(ROOT/'assets',DIST/'assets')
print('Prepared static bundle in dist/')
